package com.witchersbestiary.merchant;
import net.minecraft.server.*;import net.minecraft.server.world.ServerWorld;import net.minecraft.util.math.*;import net.minecraft.world.*;import net.minecraft.block.*;import net.minecraft.registry.tag.BlockTags;import net.minecraft.entity.EntityType;
import com.witchersbestiary.board.VisitedVillageBoards;
/** Bounded loaded-chunk discovery. No locate calls, chunk generation, tickets or world edits. */
public final class MerchantSpawns {
 private static int cursor;
 public static boolean safe(ServerWorld w,BlockPos pos){if(w.getChunkManager().getWorldChunk(pos.getX()>>4,pos.getZ()>>4)==null||w.isOutOfHeightLimit(pos.up(2))||!w.getWorldBorder().contains(pos))return false;
  for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++){var at=pos.add(x,0,z);if(w.getChunkManager().getWorldChunk(at.getX()>>4,at.getZ()>>4)==null)return false;var floor=w.getBlockState(at.down());if(!(floor.isIn(BlockTags.DIRT)||floor.isIn(BlockTags.SAND)||floor.isOf(Blocks.STONE)||floor.isOf(Blocks.GRAVEL)||floor.isOf(Blocks.SNOW_BLOCK))||floor.isOf(Blocks.DIRT_PATH)||!floor.isSideSolidFullSquare(w,at.down(),Direction.UP))return false;if(!w.getBlockState(at).isAir()||!w.getBlockState(at.up()).isAir()||!w.getFluidState(at).isEmpty())return false;}
  var box=new Box(pos).expand(2,0,2).stretch(0,2,0);return w.isSpaceEmpty(box)&&w.getOtherEntities(null,box).isEmpty();
 }
 public static boolean village(ServerWorld w,String key,BlockPos center){var ledger=MerchantLedger.get(w.getServer());if(ledger.readOnly())return false;var claim=ledger.villages.computeIfAbsent(key,k->new MerchantLedger.Claim());if(claim.entity!=null||claim.attempts>=12||w.getTime()<claim.next)return false;
  var existing=w.getEntitiesByType(ArcaneMerchants.TYPE,e->e.mode()==ArcaneMerchant.Mode.VILLAGE&&e.village().equals(key));if(!existing.isEmpty()){claim.entity=existing.getFirst().getUuid();ledger.markDirty();return false;}
  claim.attempts++;claim.next=w.getTime()+1200;ledger.markDirty();for(int i=0;i<9;i++){int angle=(claim.attempts*5+i)*37;int x=center.getX()+(int)(Math.cos(Math.toRadians(angle))*(5+i*2)),z=center.getZ()+(int)(Math.sin(Math.toRadians(angle))*(5+i*2));if(w.getChunkManager().getWorldChunk(x>>4,z>>4)==null)continue;var pos=new BlockPos(x,w.getTopY(Heightmap.Type.MOTION_BLOCKING_NO_LEAVES,x,z),z);if(!safe(w,pos))continue;var npc=ArcaneMerchants.TYPE.create(w);if(npc==null)return false;npc.refreshPositionAndAngles(x+.5,pos.getY(),z+.5,w.random.nextFloat()*360,0);npc.village(key,pos);if(w.spawnEntity(npc)){claim.entity=npc.getUuid();ledger.markDirty();return true;}}return false;
 }
 private static void discover(MinecraftServer s){var players=s.getPlayerManager().getPlayerList();if(players.isEmpty())return;var p=players.get(Math.floorMod(cursor++,players.size()));var w=p.getServerWorld();if(w.getRegistryKey()!=World.OVERWORLD)return;var cp=p.getChunkPos();var loaded=w.getChunkManager().getWorldChunk(cp.x,cp.z);if(loaded==null)return;int examined=0;for(var ref:loaded.getStructureReferences().entrySet()){if(!VisitedVillageBoards.supported(w,ref.getKey()))continue;for(long packed:ref.getValue()){if(++examined>16)return;var origin=new ChunkPos(packed);var chunk=w.getChunkManager().getWorldChunk(origin.x,origin.z);if(chunk==null)continue;var start=chunk.getStructureStart(ref.getKey());if(start==null||!start.hasChildren())continue;var box=start.getChildren().isEmpty()?start.getBoundingBox():start.getChildren().getFirst().getBoundingBox();String key=w.getRegistryKey().getValue()+"/"+w.getRegistryManager().get(net.minecraft.registry.RegistryKeys.STRUCTURE).getId(ref.getKey())+"/"+packed;village(w,key,new BlockPos((box.getMinX()+box.getMaxX())/2,0,(box.getMinZ()+box.getMaxZ())/2));}}}
 private static void wander(MinecraftServer s){var w=s.getOverworld();var ledger=MerchantLedger.get(s);if(ledger.readOnly()||w.getTime()<ledger.nextWander)return;ledger.nextWander=w.getTime()+12000;ledger.markDirty();var players=w.getPlayers(p->p.isAlive()&&!p.isSpectator());if(players.isEmpty())return;var p=players.get(w.random.nextInt(players.size()));if(!w.getEntitiesByType(ArcaneMerchants.TYPE,e->e.mode()==ArcaneMerchant.Mode.WANDERING).isEmpty())return;
  for(int i=0;i<12;i++){double angle=w.random.nextDouble()*Math.PI*2;int range=40+w.random.nextInt(25),x=p.getBlockX()+(int)(Math.cos(angle)*range),z=p.getBlockZ()+(int)(Math.sin(angle)*range);if(w.getChunkManager().getWorldChunk(x>>4,z>>4)==null)continue;var pos=new BlockPos(x,w.getTopY(Heightmap.Type.MOTION_BLOCKING_NO_LEAVES,x,z),z);if(!safe(w,pos))continue;var npc=ArcaneMerchants.TYPE.create(w);if(npc==null)return;npc.refreshPositionAndAngles(x+.5,pos.getY(),z+.5,w.random.nextFloat()*360,0);if(w.spawnEntity(npc))return;}
 }
 public static void initialize(){net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents.END_SERVER_TICK.register(s->{if(s.getTicks()%200==0)discover(s);if(s.getTicks()%400==0)wander(s);});}
}
